-- Billing (docs/plan.md §1.17, §1.24): Mezonas' billing settings and unit costs (global, one
-- settings row), and per client the usage reports sent to Stripe and the Stripe events received.
-- New tables only, so the previous Worker keeps working. Generated by drizzle-kit; the grants,
-- row-level security, immutability trigger and default settings at the end are hand-written.
CREATE TABLE "billing_event" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"stripe_event_id" text NOT NULL,
	"type" text NOT NULL,
	"object_id" text,
	"summary" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"stripe_created_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "billing_event_stripe_event_id_unique" UNIQUE("stripe_event_id")
);
--> statement-breakpoint
CREATE TABLE "billing_setting" (
	"id" integer PRIMARY KEY DEFAULT 1 NOT NULL,
	"allowance_credits_per_agent" integer NOT NULL,
	"base_price_id" text,
	"overage_price_id" text,
	"meter_event_name" text NOT NULL,
	"days_until_due" integer DEFAULT 30 NOT NULL,
	"base_fee" numeric(14, 4),
	"overage_price" numeric(14, 4),
	"currency" text DEFAULT 'USD' NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_by" uuid,
	CONSTRAINT "billing_setting_singleton_check" CHECK ("billing_setting"."id" = 1),
	CONSTRAINT "billing_setting_allowance_check" CHECK ("billing_setting"."allowance_credits_per_agent" >= 0),
	CONSTRAINT "billing_setting_days_until_due_check" CHECK ("billing_setting"."days_until_due" between 1 and 365)
);
--> statement-breakpoint
CREATE TABLE "billing_unit_cost" (
	"measure" text PRIMARY KEY NOT NULL,
	"unit_cost" numeric(14, 4) NOT NULL,
	"per_units" integer DEFAULT 1 NOT NULL,
	"currency" text DEFAULT 'USD' NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_by" uuid,
	CONSTRAINT "billing_unit_cost_per_units_check" CHECK ("billing_unit_cost"."per_units" > 0),
	CONSTRAINT "billing_unit_cost_nonnegative_check" CHECK ("billing_unit_cost"."unit_cost" >= 0)
);
--> statement-breakpoint
CREATE TABLE "billing_usage_report" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"period" date NOT NULL,
	"day" date NOT NULL,
