	"allowance" integer NOT NULL,
	"credits" integer NOT NULL,
	"overage" integer NOT NULL,
	"quantity" integer NOT NULL,
	"cost_usd" numeric(14, 4) DEFAULT '0' NOT NULL,
	"currency" text DEFAULT 'USD' NOT NULL,
	"identifier" text NOT NULL,
	"status" text NOT NULL,
	"error" text,
	"sent_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "billing_usage_report_day_key" UNIQUE("tenant_id","period","day"),
	CONSTRAINT "billing_usage_report_status_check" CHECK ("billing_usage_report"."status" in ('pending', 'sent', 'failed', 'none')),
	CONSTRAINT "billing_usage_report_counts_check" CHECK ("billing_usage_report"."quantity" >= 0 and "billing_usage_report"."overage" >= 0 and "billing_usage_report"."credits" >= 0 and "billing_usage_report"."allowance" >= 0)
);
