-- Settings change in place (the back office edits them, and may drop a measure's unit cost);
-- reports change only their status; events are written once. No history is deleted.
GRANT SELECT, INSERT, UPDATE ON billing_setting, billing_unit_cost, billing_usage_report TO cs_runtime;
--> statement-breakpoint
GRANT DELETE ON billing_unit_cost TO cs_runtime;
--> statement-breakpoint
GRANT SELECT, INSERT ON billing_event TO cs_runtime;
