DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['billing_usage_report', 'billing_event'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I FOR ALL TO PUBLIC '
      'USING (tenant_id = any(app_tenant_ids())) '
      'WITH CHECK (tenant_id = any(app_tenant_ids()))', t);
  END LOOP;
END
$$;
--> statement-breakpoint
CREATE TRIGGER billing_usage_report_immutable BEFORE UPDATE OR DELETE ON billing_usage_report
  FOR EACH ROW EXECUTE FUNCTION forbid_update_except('status', 'error', 'sent_at');
--> statement-breakpoint
CREATE TRIGGER billing_event_immutable BEFORE UPDATE OR DELETE ON billing_event
  FOR EACH ROW EXECUTE FUNCTION forbid_update_except();
--> statement-breakpoint

-- The settings are global (no client): every session reads them, only operator sessions write them.
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['billing_setting', 'billing_unit_cost'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY read_all ON %I FOR SELECT TO PUBLIC USING (true)', t);
    EXECUTE format(
      'CREATE POLICY operator_insert ON %I FOR INSERT TO PUBLIC WITH CHECK (app_is_operator())', t);
    EXECUTE format(
      'CREATE POLICY operator_update ON %I FOR UPDATE TO PUBLIC '
      'USING (app_is_operator()) WITH CHECK (app_is_operator())', t);
  END LOOP;
END
$$;
--> statement-breakpoint
CREATE POLICY operator_delete ON billing_unit_cost FOR DELETE TO PUBLIC USING (app_is_operator());
